def count_urls_in_json(json_str, top_n=10):
    data = json.loads(json_str)
    counts = Counter()

    def walk(value):
        if isinstance(value, dict):
            for v in value.values():
                walk(v)
        elif isinstance(value, list):
            for v in value:
                walk(v)
        elif isinstance(value, str) and value.startswith(("http://", "https://", "www.")):
            counts[value] += 1

    walk(data)
    return dict(counts.most_common(top_n))

import re

def error_times_and_average(logs):
    times = []
    for log in logs:
        if "ERROR" in log:
            m = re.search(r'(\d{2}):(\d{2}):\d{2}', log)
            if m:
                times.append((int(m.group(1)), int(m.group(2))))
    if not times:
        return times, (0, 0)
    avg = sum(h * 60 + mi for h, mi in times) // len(times)
    return times, divmod(avg, 60)

